import java.util.Scanner;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputs = scanner.nextLine().split(" ");
        int n = Integer.parseInt(inputs[0]);
        int m = Integer.parseInt(inputs[1]);
        int[] sorted = {n, m};
        if (sorted[0] > sorted[1]) {
            int temp = sorted[0];
            sorted[0] = sorted[1];
            sorted[1] = temp;
        }
        n = sorted[0];
        m = sorted[1];

        int delta;
        if (n == 1) {
            delta = Math.min(m % 6, 6 - m % 6);
        } else if (n == 2) {
            Map<Integer, Integer> map = Map.of(2, 4, 3, 2, 7, 2);
            delta = map.getOrDefault(m, 0);
        } else {
            delta = (n & 1) * (m & 1);
        }
        System.out.println(n * m - delta);
        scanner.close();
    }
}
